// ---- Settings you can edit --------------------------------------------------------------------------------
const settings = {
  sheetId: '',               // the Google Sheet id: the long part of its URL between /d/ and /edit
  sheetName: 'Kling queue',  // the tab with the columns from kling-queue-sheet.csv
  model: 'kling-v4-0',       // used when a row leaves model empty: kling-v4-0, kling-v3-0, kling-v3-0-turbo, kling-v2-6 ...
  mode: 'std',               // std (720p) or pro (1080p, paid Kling plan). v3 also takes 4k
  duration: 5,               // seconds. Kling 4.0: 3-30, v3: 3-15, older models: 5 or 10
  aspectRatio: '16:9',       // text-to-video only (image-to-video keeps the image's shape): 16:9, 9:16, 1:1, 21:9 (4.0)
  maxStartsPerTick: 10,      // at most this many new jobs per tick, and never more than your accounts' free job slots
  maxPollsPerTick: 25,       // at most this many running rows read per tick
  cleanMaster: true,         // true = link the clean, non-watermarked master (paid Kling plans), else the preview
  saveToDrive: false,        // true = also copy each finished video to Google Drive (folder below)
  driveFolderId: '',         // empty = the root of My Drive
};
// -----------------------------------------------------------------------------------------------------------
let fromForm = false;
try { fromForm = $('Add to the Kling queue').isExecuted; } catch (e) { fromForm = false; }
if (!settings.sheetId) throw new Error('Set sheetId in the Settings node: the id of your Google Sheet.');
return [{ json: { ...settings, fromForm } }];

// One row per line: "prompt | start image link | end image link". The engine checks each row when it starts it.
const f = $('Add to the Kling queue').first().json;
const mode = /^pro/.test(String(f['Quality'] || '')) ? 'pro' : 'std';
const pin = String(f['Kling account (optional)'] || '').trim();
const rows = String(f['Prompts'] || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean).slice(0, 200).map(line => {
  const [prompt, image, tail] = line.split('|').map(s => s.trim());
  return { json: { prompt: prompt || '', image_url: image || '', end_image_url: tail || '', model: f['Model'] || '', mode,
    duration: String(f['Duration (seconds)'] || ''), aspect_ratio: image ? '' : (f['Aspect ratio (text-to-video)'] || ''),
    email: pin, status: 'new', note: `added from the form ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC` } };
});
if (!rows.length) throw new Error('No prompts in the form.');
return rows;

const apiErr = j => {
  if (!j || !j.error || j.task || j.status_name !== undefined || j.cdnUrl || j.session) return null;  // a Kling answer may carry its own error text
  const e = j.error;
  const msg = typeof e === 'string' ? e : String(e.message || '');
  let body = typeof e === 'string' ? j : null;
  const m = msg.match(/^(\d{3}) - ([\s\S]*)$/);
  if (m) { try { body = JSON.parse(m[2]); if (typeof body === 'string') body = JSON.parse(body); } catch (x) { body = null; } }
  // n8n keeps the answer's body in the message for most codes ('400 - "{...}"'), but swaps in its own text for some
  // (429: "Try spacing your requests out..."): then only error.status carries the HTTP code.
  const code = Number((body && body.code) || (m && m[1]) || (typeof e === 'object' && (e.status || e.httpCode)) || 0) || 0;
  const plain = { 429: 'every Kling account is running at its job limit', 502: 'bad gateway', 504: 'timed out', 500: 'server error' };
  const text = (body && typeof body.error === 'string' && body.error) || (!m && plain[code]) || (typeof e === 'object' && e.description) || msg || 'no answer';
  return { code, text: String(text).slice(0, 500) };
