const clean = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n || 200);
const stamp = () => new Date().toISOString().slice(0, 16).replace('T', ' ') + ' UTC';

// The clean master when the Kling plan allows it (GET /assets/download), else the preview, plus the account's
// real credit balance read right now (Kling counts it in hundredths of a credit).
const S = $('Settings').first().json;
return $input.all().map((it, i) => {
  const t = $('Task result').itemMatching(i).json;
  const c = $('Clean link').itemMatching(i).json;
  const cdn = !apiErr(c) && c && c.cdnUrl ? c.cdnUrl : '';
  const url = S.cleanMaster && cdn ? cdn : t.preview;
  const total = !apiErr(it.json) && it.json.balance ? it.json.balance.total : null;
  const u = { ...t.update, status: 'done', finished: stamp(), video_url: url,
    credits_left: total == null ? '' : (Number(total) / 100).toFixed(2),
    note: S.cleanMaster && !cdn ? 'Preview with watermark: the clean master needs a paid Kling plan.' : '' };
  return { json: { update: u, drive: !!S.saveToDrive, url, name: `kling-row-${u.row_number}-${t.task_id}.mp4` } };
});

return $input.all().map((it, i) => {
  const f = $('Finish row').itemMatching(i).json;
  const u = { ...f.update };
  if (it.json.id) u.drive_link = `https://drive.google.com/file/d/${it.json.id}/view`;
  else u.note = `Done, but the Drive copy failed (${(it.json.error && it.json.error.message) || 'no answer'}). video_url still has it.`;
  return { json: { update: u } };
});
